// Offline cache for the THE LAB prototype. Generated by scripts/add-pwa.mjs.
const CACHE = 'thelab-81e80452191a';
const FILES = ["./","app.css","app.js","assets/adapt.png","assets/ascent.png","assets/balance.png","assets/bebas-neue-latin-400-normal.woff2","assets/floor.jpg","assets/forge.png","assets/hero.png","assets/hybrid.png","assets/load.png","assets/logo.png","assets/lounge.jpg","assets/mark.png","assets/montserrat-latin-500-normal.woff2","assets/montserrat-latin-600-normal.woff2","assets/montserrat-latin-700-normal.woff2","assets/pulse.png","assets/range.png","assets/recovery.jpg","assets/tribe.png","icons/apple-touch-icon.png","icons/favicon-32.png","icons/icon-192.png","icons/icon-512.png","icons/icon-maskable-512.png","index.html","manifest.webmanifest","mobile-preview.html","pwa.js"];

// Some hosts redirect /page.html to /page (Cloudflare Pages does). A cached redirect can't be
// served to a page navigation, so store the final response as a plain copy under the .html name.
const plain = (res) => (res.redirected
  ? res.blob().then((body) => new Response(body, { status: res.status, statusText: res.statusText, headers: res.headers }))
  : res);

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE)
      .then((c) => Promise.all(FILES.map((f) => fetch(f, { cache: 'reload' }).then((res) => {
        if (!res.ok) throw new Error(f + ' ' + res.status);
        return Promise.resolve(plain(res)).then((copy) => c.put(f, copy));
      }))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('thelab-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

// Cache first. Pages opened with ?app=1 match the cached page, and a page reached at its
// short address (/mobile-preview after a host redirect) matches the cached .html file.
self.addEventListener('fetch', (event) => {
  const req = event.request;
  const url = new URL(req.url);
  if (req.method !== 'GET' || url.origin !== self.location.origin) return;
  const nav = req.mode === 'navigate';
  event.respondWith(
    caches.match(req, { ignoreSearch: nav })
      .then((hit) => hit || (nav && !url.pathname.endsWith('/') && !url.pathname.endsWith('.html') ? caches.match(url.pathname + '.html', { ignoreSearch: true }) : undefined))
      .then((hit) => hit || fetch(req)),
  );
});
